// Fondo de partículas del hero — versión optimizada (2026-10-09):
// pausa cuando el hero no está a la vista o la pestaña está oculta,
// menos partículas en pantallas chicas, sin gradiente ni sombra por cuadro,
// y respeta "reducir movimiento" del sistema.
(function(){
  const canvas=document.getElementById("particles-canvas"),heroEl=document.getElementById("hero");
  if(!canvas||!heroEl)return;
  const ctx=canvas.getContext("2d");
  const reduce=window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  let W=0,H=0,running=false,visible=true,rafId=0;
  const mouse={x:-9999,y:-9999};
  const COUNT=window.innerWidth<768?38:70,DIST=150,DIST2=DIST*DIST;
  const COLORS=["0,255,136","0,229,204"];
  function resize(){W=canvas.width=heroEl.offsetWidth;H=canvas.height=heroEl.offsetHeight}
  resize();
  let rt;window.addEventListener("resize",()=>{clearTimeout(rt);rt=setTimeout(resize,150)});
  heroEl.addEventListener("mousemove",e=>{const r=heroEl.getBoundingClientRect();mouse.x=e.clientX-r.left;mouse.y=e.clientY-r.top});
  heroEl.addEventListener("mouseleave",()=>{mouse.x=-9999;mouse.y=-9999});
  const ps=Array.from({length:COUNT},()=>({x:Math.random()*W,y:Math.random()*H,vx:(Math.random()-.5)*.35,vy:(Math.random()-.5)*.35,r:1.8*Math.random()+.6,c:COLORS[Math.random()>.5?1:0],a:.5*Math.random()+.3}));
  function step(p){const dx=mouse.x-p.x,dy=mouse.y-p.y,d=Math.sqrt(dx*dx+dy*dy);if(d<200){const k=(200-d)/200*.0012;p.vx+=dx*k;p.vy+=dy*k}
    p.vx*=.98;p.vy*=.98;p.x+=p.vx;p.y+=p.vy;
    if(p.x<-20)p.x=W+20;else if(p.x>W+20)p.x=-20;if(p.y<-20)p.y=H+20;else if(p.y>H+20)p.y=-20}
  function draw(){
    ctx.clearRect(0,0,W,H);ctx.lineWidth=.7;
    for(let i=0;i<COUNT;i++){const a=ps[i];for(let j=i+1;j<COUNT;j++){const b=ps[j],dx=a.x-b.x,dy=a.y-b.y,d2=dx*dx+dy*dy;
      if(d2<DIST2){ctx.strokeStyle="rgba("+a.c+","+((1-Math.sqrt(d2)/DIST)*.25).toFixed(3)+")";ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}}}
    for(const p of ps){ctx.fillStyle="rgba("+p.c+","+p.a+")";ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,6.2832);ctx.fill()}
  }
  function loop(){if(!running)return;ps.forEach(step);draw();rafId=requestAnimationFrame(loop)}
  function sync(){const should=visible&&!document.hidden&&!reduce;if(should&&!running){running=true;rafId=requestAnimationFrame(loop)}else if(!should&&running){running=false;cancelAnimationFrame(rafId)}}
  if("IntersectionObserver"in window){new IntersectionObserver(es=>{visible=es[0].isIntersecting;sync()}).observe(heroEl)}
  document.addEventListener("visibilitychange",sync);
  if(reduce)draw();else sync();
  document.addEventListener("DOMContentLoaded",()=>{setTimeout(()=>{document.querySelectorAll(".outline-text").forEach(t=>t.classList.add("revealed"))},300)});
  if(document.readyState!=="loading")setTimeout(()=>{document.querySelectorAll(".outline-text").forEach(t=>t.classList.add("revealed"))},300);
})();
